const destinations = $input.all();

return [
  {
    json: {
      destinations: destinations.map((item, index) => ({
        id: `destination_${index + 1}`,
        title: item.json.destination,
        description: `Explore ${item.json.destination}`
      }))
    }
  }
];

const trigger = $('WhatsApp Trigger').item.json;

const state = $json.state || null;
const updatedAt = $json.updatedAt || null;
const booking_attempts = $json.booking_attempts || 0;

let is_new_user = !state;

// Booking process ko maximum 24 hours tak active rakho
if (state === 'COLLECTING_BOOKING_INFO' && updatedAt) {
  const lastActivity = new Date(updatedAt).getTime();
  const now = Date.now();

  const hoursPassed = (now - lastActivity) / (1000 * 60 * 60);

  if (hoursPassed < 24) {
    is_new_user = false;
  } else {
    is_new_user = true;
  }

} else if (state && updatedAt) {
  const lastActivity = new Date(updatedAt).getTime();
  const now = Date.now();

  const minutesPassed = (now - lastActivity) / (1000 * 60);

  if (minutesPassed >= 15) {
    is_new_user = true;
  }
}

return [
  {
    json: {
      ...trigger,
      user_state: state,
      booking_attempts,
      is_new_user
    }
  }
];

const trigger = $('WhatsApp Trigger').item.json;
const context = $('Prepare User Context').item.json;

return [
  {
    json: {
      ...trigger,
      user_state: context.user_state,
      is_new_user: context.is_new_user,
      booking_attempts: $json.booking_attempts ?? context.booking_attempts ?? 0
    }
  }
];

const packages = $input.all();

return [
  {
    json: {
      packages: packages.map((item, index) => ({
        id: `package_${index + 1}`,
        title: item.json.Package_Name,
        description: `${item.json.Duration} • ${item.json.Price} ${item.json.Currency}`,
        package_number: index + 1
      }))
    }
  }
];

